-- GENERATED by `wfj generate` from data/gossip/gossip-38.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["3804103d8123d555"] = { "Tutti scagnozzi di capo - ⟦Stomper Kreeg=Kreeg il Pestatore⟧, tutte tre Guardie, capitano Kromcrush e Osservatore - dare tributo a nuovo capo. Se tu uccidi scagnozzo, quello scagnozzo non può dare tributo! Ognuno che tieni vivo ti dà più tributo. Tieni tutti vivi e tu prendi GRANDE tributo!\n\nSììì!", "." },
  ["38095a1bb2bcb2f7"] = { "Ah, lo sento: hai vinto la battaglia! Credo di poterti trasportare a Stratholme senza pericolo, purché tu sia già <passato/passata> dal mio collega laggiù. Entra nel cerchio e abbi pazienza...", "." },
  ["3811c70d72d3b249"] = { "Sei nat<o/a> kaldorei, figli<o/a> delle stelle, e diventerai <un/una> grande <sacerdote/sacerdotessa> della nostra dea Elune. La sua grazia può illuminare la nostra forza, guidando i nostri colpi a segno, o aiutarci a nasconderci come la luna può eclissare il sole.\r\n\nLa nostra Lunga Veglia dopo la difesa del ⟦Mount Hyjal=Monte Hyjal⟧ è finita, e ci siamo uniti a un'⟦Alliance=Alleanza⟧ con altri popoli, che incontrerai a tempo debito. Per ora sei al sicuro tra i rami di Teldrassil.\r\n\nDimostra i doni di Madre Luna e godi delle sue benedizioni.", "." },
  ["3812420aabc291f8"] = { "Benvenut<o/a> nella mia bottega, è bello vedere un altro incantatore qui a ⟦Stormwind=Roccavento⟧. Sei qui per una lezione, forse?", "." },
  ["3812b10aaa87196c"] = { "Ti do il benvenuto a Tanaris, {name}. Come posso esserti utile oggi? Non mi sembri un fabbro, ma so bene che l'apparenza può ingannare.", "." },
  ["381405be460ff50e"] = { "I ribelli di Lordaeron sono pochi e deboli, e non conoscono la gioia di servire il nostro Re dei Lich.", "." },
  ["381db94401626e56"] = { "Quando avrai raccolto abbastanza pietre di pozzo intorno ai pozzi d'acqua e Ambercorn sotto gli alberi, preparerò per te l'⟦Water of the Seers=Acqua dei Veggenti⟧.", "." },
  ["381eb92dcdc6d5c5"] = { "Mmh, ti ascolto. Di che offerta si tratta?", "." },
  ["381f62ef642d6fa0"] = { "La foresta brulica di worgen e ghoul. Bisogna fare qualcosa!", "." },
  ["382bef9404548bb5"] = { "Subito, padrone!", "." },
  ["382f590a4e41a0fb"] = { "Salve, {name}. Posso fare qualcosa per te? Magari vuoi assaggiare il nostro speciale cheddar Trias? O un pezzo di Groviera di Darnassus?", "." },
  ["38482e57bfd68674"] = { "Ho passato tutta la vita a curare questi alberi. Potandoli e nutrendoli... è giusto che mi abbiano seguito nella morte.", "." },
  ["3852c5fb2e14abff"] = { "Zug zug, amico mio! Sono Kelm Hargunth, il principale fornitore dei ⟦Warsong Outriders=Predoni Cantaguerra⟧. Man mano che migliorerai la tua reputazione presso i Predoni, metterò a tua disposizione una bella selezione di merci da usare nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧. Se avessi bisogno di riparare qualche oggetto, offro anche quel servizio.", "." },
  ["3855296bbae878eb"] = { "La forza di %s si affievolisce mentre se ne staccano pezzi di roccia", "." },
  ["385543de761d16e2"] = { "Tanaris è sotto attacco in questo momento?", "." },
  ["385b413122b3fe6d"] = { "Mi servono indicazioni.", "." },
  ["3865634957333e9b"] = { "Che conflitto inutile, ma se gli elfi della ⟦Silverwing Hold=Rocca di Alargentea⟧ non vogliono parlarci in pace, che alternativa ci lasciano? Chiedi l'aiuto di ⟦Kergul Bloodaxe=Kergul Scurerossa⟧ sull'⟦Hunter Rise=Altura dei Cacciatori⟧ per raggiungere la ⟦Warsong Gulch=Forra dei Cantaguerra⟧.", "." },
  ["3872e3b9252b4a75"] = { "La ⟦Stormpike Guard=Guardia dei Piccatonante⟧ deve essere distrutta! Sei <pronto/pronta> per la ⟦Alterac Valley=Valle d'Alterac⟧, {class}?", "." },
  ["387776bd33949a67"] = { "Ci sono cose fondamentali che devi imparare prima che io possa aiutarti. Parla con il mio apprendista, Vhan. È gentile e paziente, e ti insegnerà ciò che devi sapere.", "." },
  ["38777e8f4c22a090"] = { "Markhor, voglio lasciare il mio famiglio nella stalla.", "." },
  ["388924e3cbc6d3e4"] = { "Il maestro Woo Ping padroneggia quasi tutte le armi conosciute dall'uomo. È particolarmente letale con le tecniche di spada. Passa molto tempo al Weller's Arsenal, in attesa che arrivino nuove spedizioni di armi, se ti serve un po' di addestramento.", "." },
  ["388cd8e6703eda19"] = { "Venite tutti! Avvicinatevi! Gli elisir di Perelli vi abbaglieranno!", "." },
  ["388dcb1b1ac4a380"] = { "Quindi vorresti imparare qualcosa? Sarà un piacere farti cominciare!", "." },
  ["3897cdaa9b643769"] = { "Dopo la seconda curva ecco {name}!", "." },
  ["3898d8d19e2f7f84"] = { "Osate interrompere la nostra preghiera? Giustiziateli!", "." },
  ["3898ffd1e47efc4b"] = { "Che le ⟦Deadmines=Miniere della Morte⟧ siano la tua tomba, {name}!", "." },
  ["38a442407a4614c3"] = { "Rimpiangerai il giorno in cui mi hai sfidato, {name}.", "." },
  ["38a49b13a82bfbaf"] = { "Indietro! Stai indietro! Ho uno zaino pieno di polvere esplosiva e non ho paura di usarla! Ci farò saltare tutti in aria!\n\nOh, lascia perdere. Credevo fossi qualcun altro....", "." },
  ["38ae0b4e47480253"] = { "Un piacere, {name}. Cosa posso fare per te?", "." },
  ["38aeea27a720fe00"] = { "A quanto ho capito, <caro/cara>, è stato raccolto tutto e l'ultimo materiale bellico viene assemblato e spedito alla ⟦Cenarion Hold=Fortezza Cenariana⟧. Gli ultimi carichi dovrebbero arrivare in meno di un giorno. Quando il nostro equipaggiamento e le nostre forze saranno tutti lì, il portatore dello Scettro delle Sabbie Mutevoli potrà suonare il gong vicino ad ⟦Ahn'Qiraj=Ahn'qiraj⟧ per aprire i cancelli. Allora comincerà la guerra.", "." },
  ["38ba2cb3a5972986"] = { "La Stormpike Aid Station si trova a Dun Baldar, proprio fuori dalla caserma di Dun Baldar.\n\nAl momento nessuna delle due fazioni la controlla.", "." },
  ["38c4ec62b2803bc4"] = { "Più facile del previsto... il Sigillo di Thoradin è di nuovo intero.", "." },
  ["38c6109093624a27"] = { "Salute, {class}! Benvenut<o/a> alla ⟦Cathedral of Light=Cattedrale della Luce⟧!", "." },
  ["38ca10240789bc8d"] = { "Ecco che arriva il postino!", "." },
  ["38d990e9ac404874"] = { "Sei tu il re dei Gordok! Sei il numero uno!", "." },
  ["38dc982896c4c626"] = { "Il miglior minatore ha una presa salda sul piccone, un cuore forte nel petto e una spessa polvere nera tra i capelli.", "." },
  ["38e57dc4fa036a0b"] = { "Abbi cura di te, e porta i nostri saluti alla tua famiglia.", "." },
  ["38e5c9a06fb4700f"] = { "Aperti al pubblico! L'auto goblin è in gran forma e vincerà di sicuro! Piazzate le vostre scommesse prima che cominci la corsa!", "." },
  ["38e7c62ff6609a21"] = { "Bah! Cosa ci fa quel farabutto a mandarmi i suoi parassiti? Sparisci dalla mia vista prima che ti tolga quel che resta della tua vita. E portati via questo.", "." },
  ["38e808120d4a2fa7"] = { "A quanto pare il congegno ha bisogno di un qualche oggetto incrostato di sporcizia da pulire e di tre monete d'argento per mettersi in funzione. Se ci sono entrambe le cose, la Lavatutto 5200 dovrebbe funzionare...", "." },
  ["38e861c5cf61a55e"] = { "Su con la vita!", "." },
  ["38eb32bf8722ddda"] = { "Un eroe può morire in un solo modo, {race}: per una tragedia. Il Gran Crociato strinse un patto con lo stesso Kel'Thuzad! Si sarebbe inscenata un'imboscata che avrebbe portato alla morte di Mograine. Il genere di tradimento che può venire solo dalle azioni dei compagni più fidati e più amati.", "." },
  ["38f5d89ad5fedeec"] = { "Sì, ma io lo conosco con il suo vero nome: Eldre'Thalas. Molti, molti anni fa era un bastione di potere magico per gli elfi della notte.\n\nConosci Eldre'Thalas, giovane? Si potrebbe dire che sia una coincidenza rispetto alla mia attuale sventura... ma io non credo alle coincidenze.", "." },
  ["38fb9d82385f0028"] = { "SEI <STATO/STATA> COSÌ <SPORTIVO/SPORTIVA> L'ULTIMA VOLTA... VIENI FUORI!", "." },
  ["38fc97c4c41e72bd"] = { "Quel poco che restava dell'essenza di Thunderaan fu racchiuso in un talismano di vincolo elementale. Poi Ragnaros spezzò il talismano in due frammenti perfetti. I frammenti furono affidati ai suoi luogotenenti...", "." },
})
